import React, { useEffect, useState } from 'react';
import { getMyTestDrives } from '../services/testDriveService';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import { motion } from 'framer-motion';

const UserDashboard = () => {
  const { user } = useAuth();
  const [testDrives, setTestDrives] = useState([]);
  const [purchases, setPurchases] = useState([]);

  useEffect(() => {
    getMyTestDrives().then(res => setTestDrives(res.data)).catch(console.error);
    api.get('/purchases/my').then(res => setPurchases(res.data)).catch(console.error);
  }, []);

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ padding: '2rem', maxWidth: '800px', margin: '0 auto' }}>
      <h2 style={{ fontFamily: "'Playfair Display', serif", fontSize: '2.5rem', marginBottom: '2rem' }}>
        Личный кабинет – {user.full_name}
      </h2>

      <section style={{ marginBottom: '3rem' }}>
        <h3 style={{ borderBottom: '2px solid var(--primary)', paddingBottom: '0.5rem' }}>Мои покупки</h3>
        {purchases.length === 0 ? (
          <p>Вы ещё не совершили ни одной покупки.</p>
        ) : (
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {purchases.map((p, idx) => (
              <li key={idx} style={{
                background: 'white',
                padding: '1rem 1.5rem',
                borderRadius: '12px',
                marginBottom: '1rem',
                boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
              }}>
                <div>
                  <strong>{p.brand} {p.model}</strong> ({p.year})<br />
                  <span style={{ color: '#666', fontSize: '0.9rem' }}>Дата покупки: {new Date(p.purchase_date).toLocaleDateString()}</span>
                </div>
                <div style={{ fontSize: '1.2rem', fontWeight: 700, color: 'var(--primary)' }}>
                  {p.price.toLocaleString()} ₽
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3 style={{ borderBottom: '2px solid var(--primary)', paddingBottom: '0.5rem' }}>Заявки на тест-драйв</h3>
        {testDrives.length === 0 ? (
          <p>Нет активных заявок.</p>
        ) : (
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {testDrives.map(td => (
              <li key={td.id} style={{
                background: 'white',
                padding: '0.8rem 1.2rem',
                borderRadius: '12px',
                marginBottom: '0.5rem',
                boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
              }}>
                Авто ID: {td.car_id} | Дата: {new Date(td.preferred_date).toLocaleString()} | Статус: {td.status}
              </li>
            ))}
          </ul>
        )}
      </section>
    </motion.div>
  );
};

export default UserDashboard;
